mapper.select:
select om.order_id, om.order_no, om.pay_status, om.delivery_date, UM.user_id, UM.nickname, ( select IFNULL(SUM(product_master.amount * order_item.quantity), 0) from order_item INNER JOIN product_master ON order_item.product_id = product_master.product_id where order_item.order_id = om.order_id group by order_id ) as total_amount, dym.delivery_type_name, osm.status_id, osm.status_name, dam.delivery_address_id, dam.delivery_address, UM.tel, UM.birthday, om.create_time from order_master om INNER JOIN USER_MASTER UM ON UM.user_id = om.user_id INNER JOIN delivery_type_master dym ON dym.delivery_type_id = om.delivery_type_id INNER JOIN order_status_master osm ON osm.status_id = om.status_id LEFT JOIN delivery_address_master dam ON dam.user_id = UM.user_id AND dam.delivery_address_id = om.Delivery_address_id
AND nickname LIKE CONCAT('%', #{User.nickName}, '%')
AND om.status_id = #{Status.status_id}
AND UM.tel = #{User.tel}
AND om.create_time >= CURDATE() AND om.create_time < CURDATE() + INTERVAL 1 DAY
order by om.delivery_date desc

select om.order_id, om.order_no, om.pay_status, om.delivery_date, UM.user_id, UM.nickname, ( select IFNULL(SUM(product_master.amount * order_item.quantity), 0) from order_item INNER JOIN product_master ON order_item.product_id = product_master.product_id where order_item.order_id = om.order_id group by order_id ) as total_amount, dym.delivery_type_name, osm.status_id, osm.status_name, dam.delivery_address_id, dam.delivery_address, UM.tel, UM.birthday, om.create_time from order_master om INNER JOIN USER_MASTER UM ON UM.user_id = om.user_id INNER JOIN delivery_type_master dym ON dym.delivery_type_id = om.delivery_type_id INNER JOIN order_status_master osm ON osm.status_id = om.status_id LEFT JOIN delivery_address_master dam ON dam.user_id = UM.user_id AND dam.delivery_address_id = om.Delivery_address_id
AND UM.user_id = #{user_id}
AND om.status_id = #{status_id}
AND om.order_no = #{order_no}

