UPDATE order_master
SET pay_status = #{status_id},status_id = #{status_id}, update_time = now()
WHERE order_id = #{order_id}

UPDATE stock_master
SET stock_count = stock_count - #{quantity}, version = version + 1
WHERE product_id = #{product_id} AND version = #{version}

UPDATE stock_master
SET stock_count = stock_count + #{quantity}, version = version + 1
WHERE product_id = #{product_id} AND version = #{version}
